<script setup lang="ts">
import { appUrl } from '../../composables/appUrl';
import { Head, Link, usePage } from '@inertiajs/vue3';
import PageHead from '../../components/PageHead.vue';
import AppLayout from '../../layouts/AppLayout.vue';
import ReadyInvoice from '../../components/ReadyInvoice.vue';
import { money, type Snapshot } from '../../types/salesOrder';
defineProps<Omit<Snapshot, 'perlakuan_ppn'> & { calc: Record<string, string>; closed: boolean; canManage: boolean; canInvoice: boolean; pendingReconfirmation: boolean; exited: {id:number;nama:string;keluar_jenis:string;keluar_alasan:string}[]; revisions: {revisi:number;created_date:string}[]; invoice: { id: number; nomor: string } | null; termin?: { urutan: number; persen: string; keterangan: string }[]; invoices?: { id: number; nomor: string; termin_ke: number | null; total_tagihan: string; tanggal_bayar: string | null }[]; documents: { id: number; nama_file: string; ukuran_byte: number; created_date: string; nm_lengkap: string }[]; companyConfirmation: { id: number; surat_konfirmasi_nama: string } | null }>();
const page = usePage();
const LANGKAH: Record<string, string> = {
    open: 'Periksa isi Sales Order dan surat konfirmasi peserta. Bila sudah benar, tandai Siap dibuatkan invoice.',
    siap: 'Sales Order sudah siap. Finance membuat invoice di menu Invoicing, tab Uninvoiced.',
    invoiced: 'Semua peserta Deal sudah ditagih.',
};
const stage = (so: { status: string; status_tampil?: string }, invoice: unknown) => (so.status_tampil === 'Invoiced' ? 'invoiced' : so.status === 'siap' ? 'siap' : 'open');
const allowed = (menu: string) => ((page.props.permissions as Record<string, string[]>)?.[menu] || []).includes('View');
</script>
<template>
    <Head :title="so.nomor" />
    <AppLayout title="Sales Order">
        <PageHead :title="`Sales Order ${so.nomor}`" :description="`${quotation.kepada_nama} · ${(produk[0]?.judul) ?? ''} · ${(produk[0]?.varian) ?? ''} · program ${program.nomor}`"><Link data-tour-next="soProg" :href="appUrl(`/sales-order/program/${program.id}`)">← Sales Order {{ program.nomor }}</Link></PageHead>
        <p v-for="e in $page.props.errors" :key="String(e)" class="error" role="alert">{{ e }}</p>
        <section class="panel qv-panel" data-tour="status" aria-label="Status Sales Order">
            <div class="qv-panel-top"><span class="badge" :class="stage(so, invoice) === 'invoiced' ? 'st-deal' : so.status === 'siap' ? 'st-terkirim' : 'st-draft'">{{ so.status_tampil }}</span><span v-if="closed" class="badge st-draft">Program Closed</span></div>
            <p class="qv-next"><span class="muted">Langkah berikutnya:</span> {{ LANGKAH[stage(so, invoice)] }}</p>
            <div class="row-actions"><ReadyInvoice v-if="canManage && so.status === 'open'" :so="so" :kepada="quotation.kepada_nama" :count="peserta.length" :total="calc.grand_total!" /><a class="primary" :href="appUrl(`/sales-order/${so.id}/pdf`)" target="_blank" rel="noopener">Print Out SO</a><Link v-if="allowed('quotation_program')" :href="appUrl(`/quotation/${quotation.id}`)">Buka quotation</Link></div>
        </section>
        <section v-if="termin?.length" class="panel"><h2>Pembayaran TOP</h2><p>{{ termin.length }} termin, satu termin satu invoice.</p>
            <div class="table-wrap"><table><caption class="sr-only">Termin dan invoice</caption><thead><tr><th>Termin</th><th>Persentase</th><th>Keterangan</th><th>Invoice</th><th class="money">Total tagihan</th><th>Pembayaran</th></tr></thead>
                <tbody><tr v-for="t in termin" :key="t.urutan">
                    <td class="num">{{ t.urutan }}</td><td>{{ Number(t.persen) }}%</td><td>{{ t.keterangan }}</td>
                    <template v-for="i in [(invoices ?? []).find((x) => x.termin_ke === t.urutan)]" :key="t.urutan"><template v-if="i"><td><Link v-if="allowed('invoicing')" class="code" :href="appUrl(`/invoicing/${i.id}`)">{{ i.nomor }}</Link><span v-else class="code">{{ i.nomor }}</span></td><td class="money">{{ money(i.total_tagihan) }}</td><td><span class="badge" :class="i.tanggal_bayar ? 'st-paid' : 'st-draft'">{{ i.tanggal_bayar ? 'Dibayar' : 'Belum dibayar' }}</span></td></template><template v-else><td class="muted" colspan="3">Belum ditagih</td></template></template>
                </tr></tbody></table></div></section>
        <section class="panel"><h2><span class="section-number">1</span> Sales Order</h2><p>Tanggal tersimpan: {{ so.tanggal }} · Quotation: {{ quotation.nomor }} · Sales: {{ sales }}</p><p>Penjualan Program: {{ program.nomor }} · {{ program.jenis.toUpperCase() }}</p><p v-if="so.siap_date">Siap invoice oleh {{ so.siap_nama }} · {{ so.siap_date }}</p></section>
        <section class="panel"><h2><span class="section-number">2</span> Ditujukan Kepada</h2><p>{{ quotation.tujuan }} · {{ quotation.kepada_nama }} · u.p. {{ quotation.up_nama }}</p><p>{{ quotation.alamat }}</p><p v-if="company">Perlakuan PPN: {{ company.perlakuan_ppn || 'Belum dilengkapi' }}</p></section>
        <section class="panel"><h2><span class="section-number">3</span> Program</h2><p v-for="k in produk" :key="k.nomor">{{ k.nomor }} · {{ k.judul }} · {{ k.varian }} · {{ k.sertifikat }}</p><p>{{ program.tgl_mulai }} s.d. {{ program.tgl_selesai }} · {{ program.waktu }} · {{ program.lokasi }}</p><p>{{ program.durasi_hari }} hari · {{ program.jam_pembelajaran }} JP · {{ quotation.skema_harga === 'allin' ? 'All-in 1 company' : 'Per peserta' }}</p></section>
        <section class="panel"><h2><span class="section-number">4</span> Perhitungan</h2><p v-if="quotation.skema_harga === 'allin'">Harga all-in {{ money(quotation.harga_allin) }} · tambahan {{ calc.n_tambahan }} peserta: {{ money(calc.tambahan) }}</p><dl><template v-for="(label, key) in { subtotal: 'Subtotal', diskon: 'Diskon', dpp: 'Setelah diskon', ppn: 'PPN', biaya_lain: 'Biaya Lain-lain', grand_total: 'Total Sales Order' }" :key="key"><dt>{{ label }}</dt><dd>{{ money(calc[key]) }}</dd></template></dl></section>
        <section class="panel"><h2><span class="section-number">5</span> Dokumen Deal <span class="muted">dokumen dari customer yang diunggah saat quotation ditandai Deal</span></h2><p>{{ quotation.dokumen_keterangan }}</p><ul><li v-for="d in documents" :key="d.id"><a :href="appUrl(`/sales-order/${so.id}/documents/quotation/${d.id}?preview=1`)" target="_blank" rel="noopener">{{ d.nama_file }}</a> · {{ Math.ceil(d.ukuran_byte / 1024) }} KB · {{ d.nm_lengkap }} · {{ d.created_date }} <a :href="appUrl(`/sales-order/${so.id}/documents/quotation/${d.id}`)">Unduh</a></li></ul></section>
        <section class="panel"><h2><span class="section-number">6</span> Peserta Deal &amp; Confirmation Letter <span class="muted">surat bertanda tangan yang diunggah calon peserta lewat link Konfirmasi Kehadiran</span></h2><a :href="appUrl(`/sales-order/${so.id}/letters`)" target="_blank" rel="noopener">Confirmation Letter (semua peserta Deal)</a><div class="table-wrap"><table><caption class="sr-only">Peserta Deal</caption><thead><tr><th class="num">No</th><th>Peserta</th><th>Instansi</th><th>Kontak</th><th>Masuk lewat</th><th>Confirmation Letter</th></tr></thead><tbody><tr v-for="(p, n) in peserta" :key="p.id"><td class="num">{{ n + 1 }}</td><td><b>{{ p.nama }}</b><small>{{ p.jabatan }}</small></td><td>{{ p.instansi }}</td><td>{{ p.email }}<small>{{ p.no_wa || p.no_hp }}</small></td><td>{{ program.jenis === 'b2b' ? 'Daftar PIC' : p.sumber }}<small>{{ p.tgl_isi }}</small></td><td><template v-if="program.jenis === 'b2b' && companyConfirmation"><a :href="appUrl(`/sales-order/${so.id}/documents/company-confirmation/${companyConfirmation.id}?preview=1`)" target="_blank" rel="noopener">Lihat surat Company</a> · <a :href="appUrl(`/sales-order/${so.id}/documents/company-confirmation/${companyConfirmation.id}`)">Unduh</a></template><template v-else-if="p.surat_konfirmasi"><a :href="appUrl(`/sales-order/${so.id}/documents/confirmation/${p.id}?preview=1`)" target="_blank" rel="noopener">Lihat</a> · <a :href="appUrl(`/sales-order/${so.id}/documents/confirmation/${p.id}`)">Unduh</a></template><span v-else>Belum tersedia</span></td></tr></tbody></table></div></section>
        <section v-if="exited.length" class="panel"><h2>Peserta Keluar</h2><p v-for="p in exited" :key="p.id">{{ p.nama }}: {{ p.keluar_jenis }}. {{ p.keluar_alasan }}</p></section><section v-if="revisions.length" class="panel"><h2>Riwayat revisi Sales Order</h2><p v-for="r in revisions" :key="r.revisi"><a :href="appUrl(`/quotation/${quotation.id}/revisi/${r.revisi}/so`)" target="_blank" rel="noopener">Versi {{ r.revisi || 'awal' }}</a> {{ r.created_date }}</p></section><section class="panel"><h2><span class="section-number">7</span> Invoice <span v-if="so.status === 'open'" class="muted">belum dapat dibuat: Sales Order belum ditandai siap</span></h2><template v-if="invoice"><Link v-if="allowed('invoicing')" :href="appUrl(`/invoicing/${invoice.id}`)">{{ invoice.nomor }}</Link><p v-else>{{ invoice.nomor }}</p></template><Link v-else-if="canInvoice && !pendingReconfirmation && peserta.length && so.status === 'siap'" :href="appUrl(`/invoicing/create?id_sales_order=${so.id}`)">Buat Invoice</Link><p v-else-if="pendingReconfirmation">Menunggu seluruh konfirmasi ulang peserta Deal tuntas.</p><p v-else class="hint-line">{{ so.status === 'siap' ? 'Siap dibuatkan invoice. Invoice dibuat Finance di menu Invoicing, tab Uninvoiced.' : 'Tandai Siap dibuatkan invoice agar Sales Order ini muncul di Invoicing.' }}</p></section>
    </AppLayout>
</template>
